const crypto=require('node:crypto');
const kinds={captcha:'Пройдите CAPTCHA в окне сервиса',sms:'Введите SMS-код непосредственно в окне сервиса',signature:'Проверьте документ и подтвердите подпись в доверенном окне',login:'Выполните вход в окне сервиса'};
function waitForUser(request,kind,now=Date.now()){if(typeof kind!=='string'||!Object.hasOwn(kinds,kind))throw Error('Неизвестный шаг');if(request.status!=='pending'||!request.connection)throw Error('Нужны активное поручение и привязанное подключение');return{...request,status:'waiting_user',challenge:{id:crypto.randomUUID(),kind,instruction:kinds[kind],expiresAt:now+10*60*1000},nextStep:kinds[kind]};}
function resumeForVerification(request,challengeId,now=Date.now()){if(request.status!=='waiting_user'||request.challenge?.id!==challengeId)throw Error('Шаг уже завершён или изменился');if(now>request.challenge.expiresAt)throw Error('Шаг истёк. Создайте новое поручение после входа.');return{...request,status:'pending',challenge:null,nextStep:'Пользователь сообщил о выполнении шага; проверить состояние в сервисе. Вход/подпись не подтверждены.',steps:[...(request.steps||[]),{at:new Date(now).toISOString(),kind:'user_reported_step',externalVerified:false}]};}
module.exports={waitForUser,resumeForVerification};
